def is_prime(n: int) -> bool:
    """Checks whether the integer n is a prime number."""
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    # Check divisors from 5 up to sqrt(n), skipping even numbers and multiples of 3
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True
