def is_prime(n: int) -> bool:
    """
    Comprueba si el entero n es un número primo.
    """
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    # Optimización: comprobar divisores hasta la raíz cuadrada de n
    # Usando el patrón 6k +/- 1
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True
