def is_valid_parentheses(s: str) -> bool:
    """
    Checks if the input string has valid parentheses.
    Valid strings must close the most recently opened bracket first.
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping.keys():
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            # Ignore non-parentheses characters
            continue

    return not stack
